pub struct Backend{completion:mpsc::Sender<Completed>,pushes:Option<broadcast::Receiver<vibeface_client::ClientEvent>>,host:DesktopHost,active_record:ActiveRecord,last_record_read:tokio::time::Instant,form_id:Option<String>,reconnect:Option<ReconnectTarget>,retry_at:tokio::time::Instant,retry_attempt:u32,identity_plan:Option<(ClientKey,vibeface_client::IdentityPlan)>,active_entry:Option<Entry>,key:Option<Arc<ClientKey>>,client:Option<Client>,state:Snapshot,conversation:Option<String>,out:mpsc::Sender<Event>,snapshots:watch::Sender<Arc<Snapshot>>,attachments:BTreeMap<String,Vec<vibeface_protocol::workspace::Attachment>>}
impl Backend{
 pub fn spawn(host:DesktopHost,runtime:&tokio::runtime::Handle)->(mpsc::Sender<Command>,mpsc::Receiver<Event>,watch::Receiver<Arc<Snapshot>>,watch::Sender<bool>,tokio::task::JoinHandle<()>){
 let(tx,mut rx)=mpsc::channel(64);let(out,events)=mpsc::channel(64);let(snapshots,snapshot_rx)=watch::channel(Arc::new(Snapshot::default()));let(stop,mut stopping)=watch::channel(false);let(completion,mut completed)=mpsc::channel(64);
 let task=runtime.spawn(async move{let mut backend=Self{completion,pushes:None,host,active_record:ActiveRecord::None,last_record_read:tokio::time::Instant::now(),form_id:None,reconnect:None,retry_at:tokio::time::Instant::now(),retry_attempt:0,identity_plan:None,active_entry:None,key:None,client:None,state:Snapshot::default(),conversation:None,out,snapshots,attachments:BTreeMap::new()};backend.publish_host().await;let mut timer=tokio::time::interval(Duration::from_secs(2));
 'commands:loop{tokio::select!{biased;_=stopping.changed()=>break,
 result=completed.recv()=>{if let Some(completed)=result{if backend.client.as_ref().is_some_and(|client|client.generation()==completed.generation){match completed.result{Ok(operation)=>{if operation.state==vibeface_client::OperationState::Accepted{if let Err(error)=backend.finish_accepted_draft(&operation.id).await{let _=backend.out.send(Event::Error(format!("原输入已接收，本机提醒尚未清理：{error}"))).await;}}if let Some(id)=completed.form_id{let _=backend.out.send(Event::FormSaved(id)).await;}if completed.copy_token{if let Some(client)=backend.client.as_ref(){if let Ok(Some(token))=client.take_decision_token(&operation.id){let _=backend.out.send(Event::CopySecret(zeroize::Zeroizing::new(token.expose().to_owned()))).await;}}}if let Some(text)=completed.input{let _=backend.out.send(Event::InputStored(text)).await;}let _=backend.out.send(Event::Notice(format!("操作 {}：{:?}。已接收不代表执行完成。",operation.id,operation.state))).await;if let Err(error)=backend.refresh().await{let _=backend.out.send(Event::Error(format!("原操作已保存，工作区重新读取失败：{error}"))).await;}if completed.delivery||!backend.state.delivery.orders.is_empty()||backend.state.delivery.enabled{if let Err(error)=backend.refresh_delivery().await{let _=backend.out.send(Event::Error(format!("原订单已保存，条款或进度尚未重新确认：{error}"))).await;}}},Err(error)=>{let _=backend.out.send(Event::Error(format!("操作未完成：{error}"))).await;}}}}},
 push=async{match backend.pushes.as_mut(){Some(pushes)=>pushes.recv().await,None=>std::future::pending().await}}=>{match push{Ok(event)if backend.client.as_ref().is_some_and(|client|client.generation()==event.generation&&client.network_id()==event.network_id)=>{if let Err(error)=backend.push(event.payload).await{backend.state.status=format!("实时记录需要重新读取：{error}");let _=backend.refresh().await;}},Err(broadcast::error::RecvError::Lagged(_))=>{backend.state.status="实时记录有缺口，正在重新读取。".into();let _=backend.refresh().await;},Err(broadcast::error::RecvError::Closed)=>{backend.pushes=None;backend.state.online=false;backend.state.writable=false;backend.state.status="连接已断开，未确认的操作不会重发。".into();backend.publish();},_=>{}}},
 command=rx.recv()=>{let Some(command)=command else{break};if matches!(command,Command::Shutdown){break}let command=match command{Command::Scoped{generation,command}=>{if generation!=backend.state.generation{let _=backend.out.send(Event::Error("连接已经切换，旧页面操作未提交。".into())).await;continue}*command},command=>command};let result=tokio::select!{biased;_=stopping.changed()=>break 'commands,result=backend.run(command)=>result};if let Err(error)=result{let _=backend.out.send(Event::Error(format!("操作未完成：{error}"))).await;}},
 _=timer.tick(),if backend.client.is_some()=>{let result=tokio::select!{biased;_=stopping.changed()=>break 'commands,result=backend.maintain()=>result};if let Err(error)=result{backend.state.online=false;backend.state.writable=false;backend.state.status="连接中断，显示最近记录。结果未知的操作须先核对。".into();backend.state.error=Some(error.to_string());backend.publish();}}}}
 if let Some(client)=&backend.client{client.close();}
 match backend.host.shutdown().await{Ok(())=>{let _=backend.out.send(Event::ShutdownComplete).await;},Err(error)=>{let _=backend.out.send(Event::Error(format!("Node 未能正常停止：{error}"))).await;}}
 });(tx,events,snapshot_rx,stop,task)}

 fn publish(&self){self.snapshots.send_replace(Arc::new(self.state.clone()));}
 async fn publish_host(&self){let _=self.out.send(Event::Host(self.host.snapshot())).await;}
 fn client(&self)->Result<&Client>{self.client.as_ref().context("请先连接个人网络")}
 async fn submit(&mut self,action:Action)->Result<()>{ensure!(self.state.writable||self.state.can_configure&&matches!(&action,Action::NodeSettings(_)|Action::ProviderSettings(_)|Action::Triage(_)|Action::Relay{..}|Action::TestWebhook|Action::CreateDecisionToken{..}|Action::RevokeDecisionToken{..}|Action::ConfirmWritable),"当前会话不能写入，请先加入并完成状态核对");let copy_token=matches!(&action,Action::CreateDecisionToken{..});let delivery=matches!(&action,Action::Delivery(_));let input=if let Action::Input{input,..}=&action{Some(input.text.clone())}else{None};let client=self.client()?.clone();let generation=client.generation().to_owned();let completion=self.completion.clone();let form_id=self.form_id.clone();tokio::spawn(async move{let result=client.submit(action).await;let _=completion.send(Completed{generation,input,form_id,copy_token,delivery,result}).await;});Ok(())}
 async fn push(&mut self,event:Value)->Result<()>{let payload=if event["type"]=="changed"{&event["payload"]}else{&event};match payload["type"].as_str(){Some("disconnected")=>{self.state.online=false;self.state.writable=false;self.state.status="连接已断开，正在重连；原操作不会重新签名。".into();self.publish();},Some("records")=>{if Some(payload["conversation_id"].as_str().unwrap_or(""))==self.conversation.as_deref(){let records:ConversationRecords=serde_json::from_value(payload.clone())?;let conversation=merge_records(&self.state.conversation,records)?;self.state.questions.retain(|q|q.conversation_id!=payload["conversation_id"].as_str().unwrap_or(""));self.state.questions.extend(conversation.questions.clone());self.state.conversation=Arc::new(conversation);prune_terminal_progress(&mut self.state.live,&self.state.conversation);self.publish();self.refresh_active_record().await?;}},Some("manager_progress"|"native_progress")=>{if Some(payload["conversation_id"].as_str().unwrap_or(""))!=self.conversation.as_deref(){return Ok(())}let gap=apply_progress(&mut self.state.live,payload)?;self.publish();if gap{self.refresh().await?;}},_=>{self.refresh().await?;self.refresh_active_record().await?;}}Ok(())}

 async fn refresh(&mut self)->Result<()>{let client=self.client()?.clone();let home=client.read(ReadRequest::Home).await?;let nodes=client.read(ReadRequest::Nodes).await?;let workspace=client.read(ReadRequest::Workspace).await?;
 let write_state=client.read(ReadRequest::WriteState).await?;let mut next=self.state.clone();next.local_session=matches!(client.authority(),vibeface_client::ClientAuthority::LocalSession);next.write_state=write_state["state"].as_str().context("写入状态缺失")?.into();next.writable=client.can_write()&&next.write_state=="writable";next.can_save_locally=client.can_save_locally()&&next.write_state=="writable";next.can_manage=matches!(client.authority(),vibeface_client::ClientAuthority::Membership{can_manage:true});next.can_configure=client.can_configure_node();next.bots=decode_list(&home,"bots")?;next.nodes=decode_list(&nodes,"nodes")?;next.tasks=decode_list(&workspace,"tasks")?;next.assignments=decode_list(&workspace,"assignments")?;next.channels=decode_list(&workspace,"channels")?;next.inputs=decode_list(&workspace,"inputs")?;next.questions=decode_list(&client.read(ReadRequest::Questions).await?,"questions")?;next.notifications=decode_list(&client.read(ReadRequest::Notifications).await?,"notifications")?;
 if let Some(id)=&self.conversation{next.conversation=Arc::new(parse_conversation(client.read(ReadRequest::Conversation{conversation_id:id.clone()}).await?,id,next.bots.iter().find(|b|&b.conversation_id==id).map(|b|b.bot_id.as_str()))?);}
 next.drafts=load_draft_summaries(self.draft_dir()?).await?;next.pending=client.pending().await?.into_iter().map(|p|Pending{id:p.id,state:format!("{:?}",p.state)}).collect();next.online=true;next.synced=next.write_state!="aligning";next.status=if next.local_session{"本机会话只读。加入个人网络后才能发送签名输入。".into()}else if next.writable{"已读取当前连接。未确认的操作保留在待处理列表。".into()}else{format!("当前写入状态 {}，先核对分叉或同步状态后恢复。",next.write_state)};next.error=None;prune_terminal_progress(&mut next.live,&next.conversation);self.state=next;self.publish();Ok(())}
















}
fn memory_base(metadata:&MemoryMetadata)->Result<MemoryBase>{Ok(MemoryBase{epoch:metadata.epoch.try_into()?,version:Some(MemoryVersion{revision:metadata.revision.clone(),control_revision:metadata.control_revision.try_into()?,source_event_hash:metadata.source_event_hash.clone()})})}
fn settings_rows(value:&Value)->Vec<(String,String)>{let mut rows=vec![];if let Some(providers)=value["providers"].as_array(){for provider in providers{rows.push((provider["provider"].as_str().unwrap_or("Provider").into(),format!("{} · {}",provider["state"].as_str().unwrap_or("状态未知"),provider["readiness"]["state"].as_str().unwrap_or("尚未探测"))));}}rows}

fn same_terms(a:&TransferOrder,b:&TransferOrder)->bool{a.order_id==b.order_id&&a.intent_id==b.intent_id&&a.mode==b.mode&&a.acceptance==b.acceptance&&a.source_peer==b.source_peer&&a.receiver_peer==b.receiver_peer&&a.provider_peer==b.provider_peer&&a.name==b.name&&a.bytes==b.bytes&&a.sha256==b.sha256&&a.payment.chain_id==b.payment.chain_id&&a.payment.asset==b.payment.asset&&a.payment.delivery_fee==b.payment.delivery_fee&&a.payment.reservation_fee==b.payment.reservation_fee&&a.payment.priority_fee==b.payment.priority_fee&&a.payment.total==b.payment.total&&a.payment.gas_cap==b.payment.gas_cap&&a.payment.payer==b.payment.payer&&a.payment.provider_wallet==b.payment.provider_wallet&&a.deadlines==b.deadlines}

fn parse_optional_bool(value:&str)->Result<Option<bool>>{match value{""=>Ok(None),"true"=>Ok(Some(true)),"false"=>Ok(Some(false)),_=>anyhow::bail!("请输入 true 或 false")}}

impl Command{pub fn requires_session(&self)->bool{match self{Self::ConfirmIdentityBackup(_)|Self::ReconcileIdentity|Self::DiscardIdentity|Self::Host(_)|Self::Shutdown|Self::Disconnect|Self::Refresh=>false,Self::Save{editor,..}if matches!(editor,Editor::Connect|Editor::ConnectLocal|Editor::CreateNetwork|Editor::Join|Editor::Recovery)=>false,_=>true}}}

async fn read_draft(path:PathBuf)->Result<DurableInputDraft>{tokio::task::spawn_blocking(move||Ok(serde_json::from_slice(&vibeface_bridge::platform::privatefs::read_private_bounded(&path,1024*1024,"原生待发输入")?)?)).await?}
async fn write_draft(path:PathBuf,draft:DurableInputDraft)->Result<()>{tokio::task::spawn_blocking(move||{vibeface_bridge::platform::privatefs::create_dir(path.parent().context("待发输入缺少父目录")?)?;vibeface_bridge::platform::privatefs::write_atomic(&path,&serde_json::to_vec(&draft)?)}).await?}
async fn load_draft_summaries(directory:PathBuf)->Result<Vec<NativeDraftSummary>>{tokio::task::spawn_blocking(move||{if !directory.try_exists()?{return Ok(vec![])}let mut drafts=vec![];for entry in std::fs::read_dir(directory)?{let path=entry?.path();if path.extension().and_then(|e|e.to_str())!=Some("json"){continue}let saved:DurableInputDraft=serde_json::from_slice(&vibeface_bridge::platform::privatefs::read_private_bounded(&path,1024*1024,"原生待发输入")?)?;drafts.push(NativeDraftSummary{fingerprint:saved.fingerprint,text:saved.input.text,conversation_id:saved.conversation_id});}Ok(drafts)}).await?}

fn parse_optional_number<T:std::str::FromStr>(value:&str)->Result<Option<T>>where T::Err:std::error::Error+Send+Sync+'static{if value.is_empty(){Ok(None)}else{Ok(Some(value.parse()?))}}

async fn load_draft_attachments(directory:PathBuf)->Result<Vec<vibeface_protocol::workspace::Attachment>>{tokio::task::spawn_blocking(move||{if !directory.try_exists()?{return Ok(vec![])}let mut files=vec![];for entry in std::fs::read_dir(directory)?{let path=entry?.path();if path.extension().and_then(|e|e.to_str())!=Some("json"){continue}let saved:DurableInputDraft=serde_json::from_slice(&vibeface_bridge::platform::privatefs::read_private_bounded(&path,1024*1024,"原生待发输入")?)?;files.extend(saved.input.attachments);}Ok(files)}).await?}

async fn fetch_attachment(client:&Client,conversation:&str,file:&vibeface_protocol::workspace::Attachment)->Result<Vec<u8>>{ensure!(file.size<=64*1024*1024,"附件超过64MiB");let mut bytes=Vec::with_capacity(file.size as usize);let mut offset=0;loop{let page=client.read(ReadRequest::ArtifactBytes{conversation_id:conversation.into(),blob_hash:file.hash.clone(),offset}).await?;ensure!(page["blob_hash"]==file.hash&&page["size"].as_u64()==Some(file.size)&&page["offset"].as_u64()==Some(offset),"附件分块与原引用不一致");let part=base64::engine::general_purpose::STANDARD.decode(page["data"].as_str().context("附件内容缺失")?)?;ensure!(!part.is_empty()&&offset+part.len()as u64<=file.size,"附件分块大小无效");offset+=part.len()as u64;bytes.extend_from_slice(&part);if page["next_offset"].is_null(){break}ensure!(page["next_offset"].as_u64()==Some(offset),"附件分块游标无效");}ensure!(bytes.len()as u64==file.size&&format!("{:x}",Sha256::digest(&bytes))==file.hash,"附件摘要不一致");Ok(bytes)}
